function extractUrls(text) {
  if (!text) return [];
  const regex = /https?:\/\/[^\s)"'<>]+/g;
  const m = text.match(regex);
  return m ? Array.from(new Set(m)) : [];
}

return items.map((item) => {
  const title = item.json.title ?? '';
  const description = item.json.content ?? item.json.contentSnippet ?? item.json.description ?? '';
  const sourceUrl = item.json.link ?? '';
  const rawUrls = extractUrls(`${title}\n${description}\n${sourceUrl}`);
  return { json: { title, description, source_url: sourceUrl, raw_urls: rawUrls } };
});

const TRACKING_PARAMS = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','ref'];
const SHORT_HOSTS = new Set(['t.co','bit.ly','tinyurl.com','goo.gl','ow.ly','is.gd','buff.ly']);

function normalizeUrl(url) {
  const u = new URL(url);
  u.hash = '';
  for (const k of TRACKING_PARAMS) u.searchParams.delete(k);
  if (u.protocol === 'http:') u.protocol = 'https:';
  const s = u.toString();
  return s.endsWith('/') ? s : s + '/';
}

function isLikelyShortLink(url) {
  try {
    const u = new URL(url);
    return SHORT_HOSTS.has(u.hostname.replace(/^www\./, ''));
  } catch {
    return true;
  }
}

function tagsFromText(text) {
  const t = (text || '').toLowerCase();
  const tags = [];

  if (/\bsolana\b|\$sol\b/.test(t)) tags.push('Chain:Solana');
  if (/\bethereum\b|\$eth\b/.test(t)) tags.push('Chain:Ethereum');
  if (/\barbitrum\b|\$arb\b/.test(t)) tags.push('Chain:Arbitrum');
  if (/\bpolygon\b|\$matic\b/.test(t)) tags.push('Chain:Polygon');
  if (/\bbase\s*(chain|network|mainnet|testnet)\b|coinbase\s*base\b/.test(t)) tags.push('Chain:Base');
  if (/\boptimism\b|\$op\b/.test(t)) tags.push('Chain:Optimism');
  if (/zksync|zk\s*sync/i.test(t)) tags.push('Chain:zkSync');
  if (/\bsui\s*(network|chain|mainnet|testnet)?\b/.test(t)) tags.push('Chain:Sui');
  if (/\baptos\b|\$apt\b/.test(t)) tags.push('Chain:Aptos');
  if (/\bbnb\s*chain|binance\s*smart/i.test(t)) tags.push('Chain:BNB');
  if (/\bavax|avalanche/i.test(t)) tags.push('Chain:Avalanche');

  if (/testnet|faucet/.test(t)) tags.push('Type:Testnet');
  if (/mainnet\s*(launch|live|deploy)/.test(t)) tags.push('Type:Mainnet');
  if (/\bstake|staking|deposit/.test(t)) tags.push('Type:Stake');
  if (/\bnft\b|\bmint\b/.test(t)) tags.push('Type:NFT');

  if (/\bdefi\b|\bswap\b|\bdex\b|\blend\b|\bborrow\b/.test(t)) tags.push('Sector:DeFi');
  if (/gamefi|play.?to.?earn|p2e|\bguild\b/.test(t)) tags.push('Sector:GameFi');
  if (/socialfi|social.?fi|\bfarcaster\b|\blens\b/.test(t)) tags.push('Sector:SocialFi');
  if (/layer.?2|\bl2\b|rollup/.test(t)) tags.push('Sector:Layer2');

  if (/\bairdrop\b/.test(t)) tags.push('Signal:Airdrop');
  if (/retroactive|retrodrop/.test(t)) tags.push('Signal:Retroactive');
  if (/confirmed\s*(airdrop)?/.test(t)) tags.push('Signal:Confirmed');
  if (/potential|speculated|rumor/.test(t)) tags.push('Signal:Potential');
  if (/token\s*launch|tge\b/.test(t)) tags.push('Signal:TokenLaunch');

  return Array.from(new Set(tags));
}

function truncate(s, maxLen) {
  const str = String(s || '').trim();
  return str.length > maxLen ? str.slice(0, maxLen) + '...' : str;
}

return items
  .map((item) => {
    const title = truncate(item.json.title, 500);
    const description = truncate(item.json.description, 5000);
    const sourceUrl = String(item.json.source_url ?? '').trim();
    const rawUrls = Array.isArray(item.json.raw_urls) ? item.json.raw_urls : [];

    const text = `${title}\n${description}\n${sourceUrl}`;
    const candidate = rawUrls.find((u) => !isLikelyShortLink(u));

    if (!candidate) return null;

    let projectUrl;
    try {
      projectUrl = normalizeUrl(candidate);
    } catch {
      return null;
    }

    return {
      json: {
        title: title || projectUrl,
        description: description || title || '',
        source_url: sourceUrl || projectUrl,
        project_url: projectUrl,
        tags: tagsFromText(text),
        status: 'active'
      }
    };
  })
  .filter(Boolean);

const success = items.filter(i => !i.error).length;
const failed = items.filter(i => i.error).length;
console.log(`AirdropAlert: ${success} success, ${failed} failed`);
return [{ json: { source: 'AirdropAlert', timestamp: new Date().toISOString(), success_count: success, failed_count: failed, total: items.length } }];
